mapper.select:
SELECT uca.id AS application_id, uca.user_id, u.nick_name AS nickname, AS phone_masked, uca.pen_name, uca.direction, uca.portfolio, uca.intro, uca.contact, uca.status, uca.reject_reason, au.nick_name AS reviewer_name, uca.create_time AS submitted_at, uca.audited_at AS reviewed_at FROM user_creator_application uca JOIN sys_user u ON u.user_id = uca.user_id LEFT JOIN sys_user au ON au.user_id = uca.auditor_id WHERE 1 = 1
AND uca.status = #{status}
AND u.nick_name = #{nickname}
AND ( u.nick_name LIKE CONCAT('%', #{keyword}, '%') OR u.user_name LIKE CONCAT('%', #{keyword}, '%') OR uca.pen_name LIKE CONCAT('%', #{keyword}, '%') OR u.phonenumber LIKE CONCAT('%', #{keyword}, '%') )
AND uca.create_time >= #{beginTime}
AND uca.create_time <= #{endTime}
ORDER BY ${orderByColumn} ${isAsc}
